//! Decoder tests against **real `zstd` 1.5.7 output**, plus the streaming
//! property that unit tests structurally cannot reach.
//!
//! Fixtures are generated by the system `zstd`, not hand-rolled, so these
//! assert interoperability rather than self-consistency. A decoder that agrees
//! only with its own encoder is worthless on the wire.

use zalt_codec::Scalar;
use zalt_codec::block::{BlockHeader, BlockType};
use zalt_codec::decode::Decoder;
use zalt_codec::error::Error;
use zalt_codec::magic;
use zalt_codec::params::DecodeLimits;
use zalt_codec::{decompress, xxh64};

macro_rules! fixture {
    ($name:literal) => {
        include_bytes!(concat!("fixtures/", $name))
    };
}

const EMPTY_ZST: &[u8] = fixture!("empty.zst");
const HELLO_ZST: &[u8] = fixture!("hello.zst");
const HELLO_BIN: &[u8] = fixture!("hello.bin");
const RAND4K_ZST: &[u8] = fixture!("random4k.zst");
const RAND4K_BIN: &[u8] = fixture!("random4k.bin");
const RAND4K_NOCHECK_ZST: &[u8] = fixture!("random4k_nocheck.zst");
const RAND300K_ZST: &[u8] = fixture!("random300k.zst");
const RAND300K_BIN: &[u8] = fixture!("random300k.bin");
const TEXT_ZST: &[u8] = fixture!("text.zst");
const TEXT_BIN: &[u8] = fixture!("text.bin");

fn permissive() -> DecodeLimits {
    DecodeLimits::default()
}

// ------------------------------------------------------- interoperability

#[test]
fn decodes_real_zstd_output() {
    assert_eq!(decompress(EMPTY_ZST, permissive()).unwrap(), b"");
    assert_eq!(decompress(HELLO_ZST, permissive()).unwrap(), HELLO_BIN);
    assert_eq!(decompress(RAND4K_ZST, permissive()).unwrap(), RAND4K_BIN);
}

#[test]
fn decodes_frame_without_checksum() {
    assert_eq!(
        decompress(RAND4K_NOCHECK_ZST, permissive()).unwrap(),
        RAND4K_BIN
    );
}

/// 300 KB of incompressible data exceeds the 128 KiB block maximum, so `zstd`
/// splits it. Exercises the non-final block path and the loop back to
/// `BlockHeader`.
#[test]
#[cfg_attr(
    miri,
    ignore = "300 KB payload is slow under Miri; block paths are covered elsewhere"
)]
fn decodes_multi_block_frame() {
    let out = decompress(RAND300K_ZST, permissive()).unwrap();
    assert_eq!(out.len(), 307_200);
    assert_eq!(out, RAND300K_BIN);
}

/// The empty frame's stored checksum is the low 32 bits of `XXH64("")`.
/// Independent confirmation that both the checksum wiring and the hash itself
/// agree with the reference implementation.
#[test]
fn empty_frame_checksum_matches_reference_xxh64() {
    let stored = u32::from_le_bytes(EMPTY_ZST[EMPTY_ZST.len() - 4..].try_into().unwrap());
    assert_eq!(stored, xxh64::xxh64(b"", 0) as u32);
    assert_eq!(stored, 0x51D8_E999);
}

// --------------------------------------------------------- streaming

/// Feed `input` to the decoder in fixed-size chunks and return the output.
///
/// Note what this must *not* do: call `decompress` again after a frame has
/// completed and the input is exhausted. A completed decoder has reset to
/// expect a new frame, so an extra call on empty input reports `NeedMoreInput`
/// for a frame that was never started — which reads as truncation. The status
/// of the final call that consumed input is the answer.
fn decode_chunked(input: &[u8], chunk: usize) -> Result<Vec<u8>, Error> {
    let mut decoder = Decoder::<Scalar>::new(permissive());
    let mut out = Vec::new();
    let mut cursor = 0usize;

    while cursor < input.len() {
        let end = (cursor + chunk).min(input.len());
        let progress = decoder.decompress(&input[cursor..end], &mut out)?;

        if progress.consumed == 0 {
            // No forward motion on a non-empty slice would be an infinite loop.
            return Err(Error::Truncated);
        }
        cursor += progress.consumed;
    }

    // The decoder's state decides, not the last status: a stream ending on a
    // skippable frame finishes with `NeedMoreInput` and is complete. This
    // helper used to require `FrameComplete`, the same mistake the one-shot
    // decoder and the CLI made — so it could not have tested the fix.
    if decoder.is_between_frames() && !input.is_empty() {
        Ok(out)
    } else {
        Err(Error::Truncated)
    }
}

/// **The property that matters for a browser.** The same bytes split at every
/// possible boundary must decode identically — mid-magic, mid-frame-header,
/// mid-block-header, mid-payload, mid-checksum.
///
/// This is the class of bug unit tests cannot reach: each individual state
/// transition can be correct while the machine still loses a byte when
/// suspended at exactly the wrong place.
#[test]
fn streaming_equivalence_at_every_chunk_size() {
    // Miri interprets every operation, so the 4 KB fixtures at 72 chunk sizes
    // would take hours. It runs the small fixtures instead: the state
    // transitions exercised are identical, only the volume differs, and volume
    // is not what Miri is here to find.
    let mut cases: Vec<(&str, &[u8], &[u8])> = vec![
        ("empty", EMPTY_ZST, &b""[..]),
        ("hello", HELLO_ZST, HELLO_BIN),
    ];
    if !cfg!(miri) {
        cases.push(("rand4k", RAND4K_ZST, RAND4K_BIN));
        cases.push(("nocheck", RAND4K_NOCHECK_ZST, RAND4K_BIN));
    }

    for (name, frame, expected) in cases {
        for chunk in 1..=frame.len().min(72) {
            let got = decode_chunked(frame, chunk)
                .unwrap_or_else(|e| panic!("{name}: chunk {chunk} failed: {e}"));
            assert_eq!(got, expected, "{name}: chunk size {chunk}");
        }
    }
}

/// Byte-at-a-time over a multi-block frame: the most adversarial chunking, over
/// the frame with the most state transitions.
#[test]
#[cfg_attr(miri, ignore = "300 KB one byte at a time is hours under Miri")]
fn streaming_one_byte_at_a_time_multi_block() {
    let got = decode_chunked(RAND300K_ZST, 1).unwrap();
    assert_eq!(got, RAND300K_BIN);
}

#[test]
fn decoder_reset_allows_reuse() {
    let mut decoder = Decoder::<Scalar>::new(permissive());
    let mut out = Vec::new();
    decoder.decompress(HELLO_ZST, &mut out).unwrap();
    assert_eq!(out, HELLO_BIN);

    decoder.reset();
    let mut out2 = Vec::new();
    decoder.decompress(HELLO_ZST, &mut out2).unwrap();
    assert_eq!(out2, HELLO_BIN);
}

/// zstd streams may concatenate frames.
#[test]
fn concatenated_frames() {
    let mut joined = Vec::new();
    joined.extend_from_slice(HELLO_ZST);
    joined.extend_from_slice(HELLO_ZST);

    let out = decompress(&joined, permissive()).unwrap();
    assert_eq!(out.len(), HELLO_BIN.len() * 2);
    assert_eq!(&out[..HELLO_BIN.len()], HELLO_BIN);
    assert_eq!(&out[HELLO_BIN.len()..], HELLO_BIN);
}

// ------------------------------------------------------- skippable frames

/// Skippable frames must be stepped over silently. `dcz` dictionary transport
/// rides in one, so getting this wrong breaks a feature that has not been
/// written yet in a way that would be hard to trace.
#[test]
fn skippable_frame_before_a_real_one() {
    let payload = b"arbitrary skippable content";
    let mut stream = Vec::new();
    stream.extend_from_slice(&magic::ZSTD_SKIPPABLE_DCZ.to_le_bytes());
    stream.extend_from_slice(&(payload.len() as u32).to_le_bytes());
    stream.extend_from_slice(payload);
    stream.extend_from_slice(HELLO_ZST);

    assert_eq!(decompress(&stream, permissive()).unwrap(), HELLO_BIN);

    // And it must survive arbitrary chunking too.
    for chunk in 1..=16 {
        assert_eq!(decode_chunked(&stream, chunk).unwrap(), HELLO_BIN);
    }
}

/// The position the tests above never covered: a skippable frame **last**.
///
/// Every skippable-frame test here put the skippable frame *before* a real
/// one, and the one-shot decoder, the CLI and this file's own chunked helper
/// all judged the end of a stream by the last status returned — which after a
/// skippable frame is `NeedMoreInput`. So a stream ending on one was reported
/// truncated, by all three, and no test noticed. ZALT-archives end that way by
/// construction, which is how it was found; so does any file carrying zstd's
/// seekable-format seek table. `zstd(1)` decodes them.
#[test]
fn a_stream_may_end_with_a_skippable_frame() {
    let skippable = |payload: &[u8]| {
        let mut f = magic::ZSTD_SKIPPABLE_START.to_le_bytes().to_vec();
        f.extend_from_slice(&(payload.len() as u32).to_le_bytes());
        f.extend_from_slice(payload);
        f
    };
    let mut stream = HELLO_ZST.to_vec();
    stream.extend(skippable(b"a trailing seek table, say"));
    stream.extend(skippable(b""));
    assert_eq!(decompress(&stream, permissive()).unwrap(), HELLO_BIN);
    for chunk in 1..=16 {
        assert_eq!(
            decode_chunked(&stream, chunk).unwrap(),
            HELLO_BIN,
            "chunk {chunk}"
        );
    }

    // A stream of nothing but skippable frames is complete, and empty —
    // libzstd's `ZSTD_decompress` returns 0 for it, not an error.
    let only = skippable(b"metadata");
    assert_eq!(decompress(&only, permissive()).unwrap(), b"");
    for chunk in 1..=8 {
        assert_eq!(decode_chunked(&only, chunk).unwrap(), b"");
    }
}

/// And what must still be refused, so the fix above is not a loosening.
#[test]
fn a_stream_cut_inside_a_trailing_skippable_frame_is_still_truncated() {
    let mut stream = HELLO_ZST.to_vec();
    stream.extend_from_slice(&magic::ZSTD_SKIPPABLE_START.to_le_bytes());
    stream.extend_from_slice(&10u32.to_le_bytes());
    stream.extend_from_slice(b"short"); // 5 of the 10 declared bytes
    assert!(decompress(&stream, permissive()).is_err());
    // Cut inside the skippable header's size field.
    let header_cut = &stream[..HELLO_ZST.len() + 6];
    assert!(decompress(header_cut, permissive()).is_err());
    // A partial magic number after a complete frame.
    let mut magic_cut = HELLO_ZST.to_vec();
    magic_cut.extend_from_slice(&[0x28, 0xB5]);
    assert!(decompress(&magic_cut, permissive()).is_err());
    // Empty input is not a stream.
    assert!(decompress(&[], permissive()).is_err());
    for chunk in 1..=8 {
        assert!(decode_chunked(&stream, chunk).is_err(), "chunk {chunk}");
        assert!(decode_chunked(&magic_cut, chunk).is_err(), "chunk {chunk}");
    }
}

#[test]
fn every_magic_in_the_skippable_range_is_skipped() {
    for m in magic::ZSTD_SKIPPABLE_START..=magic::ZSTD_SKIPPABLE_END {
        let mut stream = Vec::new();
        stream.extend_from_slice(&m.to_le_bytes());
        stream.extend_from_slice(&0u32.to_le_bytes());
        stream.extend_from_slice(HELLO_ZST);
        assert_eq!(
            decompress(&stream, permissive()).unwrap(),
            HELLO_BIN,
            "magic {m:#X}"
        );
    }
}

// ------------------------------------------------------------- RLE blocks

/// `zstd` rarely emits RLE *blocks*, so this frame is built by hand. Without
/// it the `RleByte` state would be entirely untested — and it is the one place
/// where a block's stream length and decoded length differ.
#[test]
fn hand_built_rle_block() {
    let repeat = 5000u32;
    let mut frame = Vec::new();
    frame.extend_from_slice(&magic::ZSTD_FRAME.to_le_bytes());
    // Descriptor: not single-segment, no checksum, no dict, no content size.
    frame.push(0b0000_0000);
    // Window descriptor: exponent 0, mantissa 0 -> 1 KiB... too small for 5000
    // bytes of output, so use exponent 4 -> 16 KiB.
    frame.push(4 << 3);
    // Block header: last, type RLE, size = repeat.
    let raw = (repeat << 3) | (1 << 1) | 1;
    frame.push(raw as u8);
    frame.push((raw >> 8) as u8);
    frame.push((raw >> 16) as u8);
    frame.push(b'Q');

    let out = decompress(&frame, permissive()).unwrap();
    assert_eq!(out.len(), repeat as usize);
    assert!(out.iter().all(|&b| b == b'Q'));

    // One byte of payload expanding to 5000 must also survive chunking.
    for chunk in 1..=12 {
        assert_eq!(
            decode_chunked(&frame, chunk).unwrap().len(),
            repeat as usize
        );
    }
}

#[test]
fn rle_block_header_semantics() {
    let raw = (5000u32 << 3) | (1 << 1);
    let h = BlockHeader::parse([raw as u8, (raw >> 8) as u8, (raw >> 16) as u8]).unwrap();
    assert_eq!(h.block_type, BlockType::Rle);
    assert_eq!(h.stream_len(), 1, "one byte of input");
    assert_eq!(h.decoded_len(), Some(5000), "five thousand bytes of output");
}

// ------------------------------------------------------ hostile input

#[test]
fn truncated_frame_is_reported_not_panicked() {
    for cut in 1..RAND4K_ZST.len().min(64) {
        let err = decompress(&RAND4K_ZST[..cut], permissive()).unwrap_err();
        assert_eq!(err, Error::Truncated, "cut at {cut}");
    }
}

#[test]
fn corrupted_checksum_is_detected() {
    let mut bad = HELLO_ZST.to_vec();
    let n = bad.len();
    bad[n - 1] ^= 0xFF;
    assert_eq!(
        decompress(&bad, permissive()).unwrap_err(),
        Error::ChecksumMismatch
    );
}

#[test]
fn corrupted_payload_is_caught_by_the_checksum() {
    let mut bad = HELLO_ZST.to_vec();
    bad[12] ^= 0x01;
    assert_eq!(
        decompress(&bad, permissive()).unwrap_err(),
        Error::ChecksumMismatch
    );
}

#[test]
fn bad_magic_is_rejected() {
    let mut bad = HELLO_ZST.to_vec();
    bad[0] ^= 0xFF;
    assert_eq!(decompress(&bad, permissive()).unwrap_err(), Error::BadMagic);
}

/// Legacy zstd frames (v0.1–v0.7) are refused by design. Their magic numbers
/// are `0xFD2FB522` through `0xFD2FB527`.
#[test]
fn legacy_frame_magics_are_refused() {
    for legacy in 0xFD2F_B522u32..=0xFD2F_B527 {
        let mut stream = legacy.to_le_bytes().to_vec();
        stream.extend_from_slice(&[0; 16]);
        assert_eq!(
            decompress(&stream, permissive()).unwrap_err(),
            Error::BadMagic,
            "legacy magic {legacy:#X} must be refused, not attempted"
        );
    }
}

#[test]
fn reserved_block_type_is_rejected() {
    let mut frame = Vec::new();
    frame.extend_from_slice(&magic::ZSTD_FRAME.to_le_bytes());
    frame.push(0b0000_0000);
    frame.push(0);
    // Block type 3 = reserved.
    frame.extend_from_slice(&[0b0000_0111, 0, 0]);
    assert_eq!(
        decompress(&frame, permissive()).unwrap_err(),
        Error::Reserved
    );
}

/// The amplification header, refused before anything is allocated.
#[test]
fn oversized_window_refused_under_browser_policy() {
    let browser = DecodeLimits {
        max_window_log: 23,
        ..Default::default()
    };
    let mut frame = Vec::new();
    frame.extend_from_slice(&magic::ZSTD_FRAME.to_le_bytes());
    frame.push(0b0000_0000);
    frame.push(0xFF); // windowLog 41
    frame.extend_from_slice(&[0, 0, 0]);

    assert!(matches!(
        decompress(&frame, browser).unwrap_err(),
        Error::WindowTooLarge { .. }
    ));
}

/// A block claiming more output than the frame's window permits.
#[test]
fn block_larger_than_the_window_is_rejected() {
    let mut frame = Vec::new();
    frame.extend_from_slice(&magic::ZSTD_FRAME.to_le_bytes());
    frame.push(0b0000_0000);
    frame.push(0); // 1 KiB window
    // Raw block claiming 100000 bytes, well over the 1 KiB window.
    let raw = (100_000u32 << 3) | 1;
    frame.push(raw as u8);
    frame.push((raw >> 8) as u8);
    frame.push((raw >> 16) as u8);

    assert_eq!(
        decompress(&frame, permissive()).unwrap_err(),
        Error::TooLarge
    );
}

/// A frame whose declared content size does not match what it produces.
#[test]
fn lying_content_size_is_caught() {
    let mut frame = Vec::new();
    frame.extend_from_slice(&magic::ZSTD_FRAME.to_le_bytes());
    // Single segment, 1-byte content size, no checksum.
    frame.push(0b0010_0000);
    frame.push(50); // claims 50 bytes
    let raw = (4u32 << 3) | 1; // delivers 4
    frame.push(raw as u8);
    frame.push((raw >> 8) as u8);
    frame.push((raw >> 16) as u8);
    frame.extend_from_slice(b"abcd");

    assert_eq!(
        decompress(&frame, permissive()).unwrap_err(),
        Error::Malformed
    );
}

/// Output exceeding a declared content size must be stopped *while* decoding,
/// not detected afterwards — otherwise the memory is already spent.
#[test]
fn output_exceeding_declared_size_is_stopped_early() {
    let mut frame = Vec::new();
    frame.extend_from_slice(&magic::ZSTD_FRAME.to_le_bytes());
    frame.push(0b0010_0000); // single segment, 1-byte content size
    frame.push(4); // claims 4 bytes
    let raw = (100u32 << 3) | 1; // delivers 100
    frame.push(raw as u8);
    frame.push((raw >> 8) as u8);
    frame.push((raw >> 16) as u8);
    frame.extend_from_slice(&[b'x'; 100]);

    assert_eq!(
        decompress(&frame, permissive()).unwrap_err(),
        Error::TooLarge
    );
}

// ------------------------------------------------------ compressed blocks

/// **The end-to-end test.** `text.zst` is real `zstd -3` output over repetitive
/// markup: a compressed block with four-stream Huffman literals (470 bytes
/// regenerated from 296) and an FSE-coded sequences section. Decoding it byte
/// for byte exercises the entire compressed path at once — Huffman weights via
/// FSE, the four-stream jump table, all three sequence tables, the backward
/// bitstream, repeat offsets, and match execution.
#[test]
fn decodes_a_real_compressed_block() {
    let out = decompress(TEXT_ZST, permissive()).unwrap();
    assert_eq!(out.len(), TEXT_BIN.len(), "decoded length");
    assert_eq!(out, TEXT_BIN, "decoded content");
}

/// The compressed path must survive arbitrary chunking like every other path.
#[test]
#[cfg_attr(miri, ignore = "15 KB at many chunk sizes is slow under Miri")]
fn compressed_block_streams_at_every_chunk_size() {
    for chunk in [1usize, 2, 3, 7, 13, 64, 255, 1024] {
        let got = decode_chunked(TEXT_ZST, chunk).unwrap_or_else(|e| panic!("chunk {chunk}: {e}"));
        assert_eq!(got, TEXT_BIN, "chunk size {chunk}");
    }
}

/// A block type of 2 with a payload that is not a valid literals section must
/// be reported as malformed — not panic, and not be mistaken for valid.
#[test]
fn garbage_compressed_block_is_rejected() {
    let mut frame = Vec::new();
    frame.extend_from_slice(&magic::ZSTD_FRAME.to_le_bytes());
    frame.push(0b0000_0000);
    frame.push(0x40); // windowLog 18
    let raw = (10u32 << 3) | (2 << 1) | 1;
    frame.push(raw as u8);
    frame.push((raw >> 8) as u8);
    frame.push((raw >> 16) as u8);
    frame.extend_from_slice(&[0xFF; 10]);

    let err = decompress(&frame, permissive()).unwrap_err();
    assert_ne!(
        err,
        Error::ChecksumMismatch,
        "should fail before any checksum"
    );
}

/// Every truncation of a real compressed frame must be reported, never panic
/// and never silently produce partial output as though it were complete.
#[test]
#[cfg_attr(miri, ignore = "quadratic over a 2.8 KB frame")]
fn every_truncation_of_a_compressed_frame_is_handled() {
    for cut in 1..TEXT_ZST.len() {
        if let Ok(out) = decompress(&TEXT_ZST[..cut], permissive()) {
            panic!("cut at {cut} decoded {} bytes as complete", out.len());
        }
    }
}

// ------------------------------------------------------------ error ABI

/// Error codes cross a C FFI and eventually a WIT boundary, where they are ABI.
/// Reordering the variants must not silently change what a caller reads.
#[test]
fn error_codes_are_stable_and_distinct() {
    let all = [
        Error::BadMagic,
        Error::Reserved,
        Error::WindowTooLarge {
            requested_log: 0,
            limit_log: 0,
        },
        Error::OffsetTooLarge {
            offset: 0,
            available: 0,
        },
        Error::Malformed,
        Error::NoPriorTable,
        Error::TooLarge,
        Error::ChecksumMismatch,
        Error::Truncated,
        Error::DictionaryRequired { id: 0 },
        Error::Unimplemented(zalt_codec::Feature::CompressedBlocks),
    ];
    let mut codes: Vec<u32> = all.iter().map(|e| e.code()).collect();
    let count = codes.len();
    codes.sort_unstable();
    codes.dedup();
    assert_eq!(codes.len(), count, "error codes must be distinct");
    assert_eq!(codes[0], 1, "zero is reserved for success at the boundary");
}

// ------------------------------------------------------ bounded history

/// **The property the window exists for.** The caller drains and *discards*
/// output after every call, keeping nothing. Decoding must still be correct,
/// because match history now lives in the decoder rather than in the caller's
/// buffer.
///
/// Before the window landed this test could not pass: matches indexed into the
/// caller's `Vec`, so clearing it corrupted every later match. That is what
/// forced a caller to hold an entire frame in memory.
#[test]
fn caller_may_discard_output_between_calls() {
    let mut decoder = Decoder::<Scalar>::new(permissive());
    let mut scratch = Vec::new();
    let mut collected = Vec::new();
    let mut cursor = 0usize;

    while cursor < TEXT_ZST.len() {
        let end = (cursor + 97).min(TEXT_ZST.len());
        let progress = decoder
            .decompress(&TEXT_ZST[cursor..end], &mut scratch)
            .unwrap();
        cursor += progress.consumed;

        // Take everything produced and throw the buffer away.
        collected.extend_from_slice(&scratch);
        scratch.clear();
    }

    assert_eq!(collected, TEXT_BIN);
}

/// A frame declaring a large window but producing little must not allocate the
/// window it declared. This is the lazy-allocation property from §6 — both a
/// security bound and, with many small resources in flight, a performance one.
#[test]
fn a_large_declared_window_does_not_allocate_eagerly() {
    let mut decoder = Decoder::<Scalar>::new(permissive());
    let mut out = Vec::new();

    // hello.zst is a single-segment frame, but random4k declares a real window.
    decoder.decompress(RAND4K_ZST, &mut out).unwrap();
    assert_eq!(out, RAND4K_BIN);

    assert!(
        decoder.heap_footprint() < 64 * 1024,
        "decoding 4 KB should not hold {} bytes",
        decoder.heap_footprint()
    );
}

/// Window memory must be bounded by the frame's declared window, not by how
/// much the frame decodes to.
#[test]
fn window_memory_stays_bounded_across_a_large_frame() {
    let mut decoder = Decoder::<Scalar>::new(permissive());
    let mut scratch = Vec::new();
    let mut total = 0usize;
    let mut cursor = 0usize;

    while cursor < RAND300K_ZST.len() {
        let end = (cursor + 4096).min(RAND300K_ZST.len());
        let progress = decoder
            .decompress(&RAND300K_ZST[cursor..end], &mut scratch)
            .unwrap();
        cursor += progress.consumed;
        total += scratch.len();
        scratch.clear();
    }

    assert_eq!(total, RAND300K_BIN.len());
    // The frame is single-segment, so its window is its whole content — the
    // bound the format itself imposes. What matters is that nothing beyond it
    // is retained.
    assert!(
        decoder.heap_footprint() <= 512 * 1024 + RAND300K_BIN.len(),
        "footprint {} exceeds the declared window plus block buffers",
        decoder.heap_footprint()
    );
}

// ------------------------------------------------ block-level size bounds

/// Build a single-block frame with the given block payload and window log.
fn framed(block: &[u8], window_log_byte: u8, block_type: u32) -> Vec<u8> {
    let mut f = Vec::new();
    f.extend_from_slice(&magic::ZSTD_FRAME.to_le_bytes());
    f.push(0b0000_0000); // windowed, no checksum, no content size
    f.push(window_log_byte);
    let raw = ((block.len() as u32) << 3) | (block_type << 1) | 1;
    f.push(raw as u8);
    f.push((raw >> 8) as u8);
    f.push((raw >> 16) as u8);
    f.extend_from_slice(block);
    f
}

/// **A block-level allocation bomb.** `Regenerated_Size` is a 20-bit field, so
/// a three-byte literals header can claim 1,048,575 bytes — eight times the
/// largest block the format allows. Four bytes of input must not be able to
/// request a megabyte.
///
/// The assertion is on *which* error: `TooLarge` proves the size bound fired.
/// Before the bound existed this returned `Truncated` — it allocated the whole
/// megabyte and only failed later, for an unrelated reason.
#[test]
fn oversized_literals_section_is_refused_before_allocating() {
    let regen: u32 = 0xF_FFFF;
    let b0 = (((regen & 0xF) << 4) as u8) | (3 << 2) | 1; // RLE, size_format 11
    let b1 = ((regen >> 4) & 0xFF) as u8;
    let b2 = ((regen >> 12) & 0xFF) as u8;
    let frame = framed(&[b0, b1, b2, 0x41], 0x00, 2); // 1 KiB window

    assert_eq!(
        decompress(&frame, permissive()).unwrap_err(),
        Error::TooLarge,
        "must be refused for size, not stumbled over later"
    );
}

/// The same bound applies to sequences. `Number_of_Sequences` reaches ~98,000
/// in three bytes, and every sequence emits a match of at least three bytes, so
/// a 1 KiB block cannot legitimately hold more than 341 of them.
#[test]
fn implausible_sequence_count_is_refused() {
    // Empty raw literals, then a 3-byte count of 0x7F00 + 0xFFFF.
    let block = [
        0x00, // raw literals, size_format 00, regenerated 0
        0xFF, 0xFF, 0xFF, // Number_of_Sequences ~ 98303
        0x00, // symbol compression modes
        0x01, // a byte of bitstream
    ];
    let frame = framed(&block, 0x00, 2); // 1 KiB window

    assert_eq!(
        decompress(&frame, permissive()).unwrap_err(),
        Error::TooLarge
    );
}

/// A literals section exactly at the block maximum is legal and must not be
/// caught by the bound above — the check is `>`, not `>=`.
#[test]
fn literals_exactly_at_the_block_maximum_are_accepted() {
    // Window log 10 -> 1 KiB block max. RLE literals of exactly 1024 bytes.
    let regen: u32 = 1024;
    let b0 = (((regen & 0xF) << 4) as u8) | (3 << 2) | 1;
    let b1 = ((regen >> 4) & 0xFF) as u8;
    let b2 = ((regen >> 12) & 0xFF) as u8;
    // Literals consume the whole block; a zero-sequence count follows.
    let block = [b0, b1, b2, 0x41, 0x00];
    let frame = framed(&block, 0x00, 2);

    let out = decompress(&frame, permissive()).unwrap();
    assert_eq!(out.len(), 1024);
    assert!(out.iter().all(|&b| b == 0x41));
}

// ------------------------------------------------------ buffer donation

/// Buffers detach and reattach, so a host can own the memory.
#[test]
fn buffers_round_trip_through_a_host_free_list() {
    let mut decoder = Decoder::<Scalar>::new(permissive());
    let mut out = Vec::new();
    decoder.decompress(TEXT_ZST, &mut out).unwrap();
    assert_eq!(out, TEXT_BIN);

    let held = decoder.heap_footprint();
    assert!(held > 0);

    let buffers = decoder.take_buffers();
    assert!(buffers.capacity() >= held, "capacity must come with them");
    assert_eq!(
        decoder.heap_footprint(),
        0,
        "a decoder that surrendered its buffers holds nothing"
    );

    // The host lends them to a different decoder.
    let mut other = Decoder::<Scalar>::new(permissive());
    other.donate_buffers(buffers);
    assert!(
        other.heap_footprint() > 0,
        "donation must transfer capacity"
    );

    let mut out2 = Vec::new();
    other.decompress(TEXT_ZST, &mut out2).unwrap();
    assert_eq!(out2, TEXT_BIN, "a donated decoder must still decode");
}

/// Donating small buffers must not discard larger ones already held — a host
/// recycling a tiny buffer should not silently shrink a busy decoder.
#[test]
fn donation_never_shrinks_a_decoder() {
    let mut big = Decoder::<Scalar>::new(permissive());
    let mut out = Vec::new();
    big.decompress(TEXT_ZST, &mut out).unwrap();
    let before = big.heap_footprint();

    big.donate_buffers(zalt_codec::Buffers::default());
    assert_eq!(
        big.heap_footprint(),
        before,
        "empty donation changed nothing"
    );
}

/// A decoder whose buffers were taken mid-frame must not silently continue
/// with half a frame's state.
#[test]
fn taking_buffers_resets_decode_state() {
    let mut decoder = Decoder::<Scalar>::new(permissive());
    let mut out = Vec::new();
    // Feed only part of a frame.
    decoder.decompress(&TEXT_ZST[..64], &mut out).unwrap();
    assert!(decoder.frame_header().is_some());

    let _ = decoder.take_buffers();
    assert_eq!(decoder.decoded_len(), 0);
    assert!(decoder.frame_header().is_none());

    // And it can start a fresh frame cleanly.
    let mut out2 = Vec::new();
    decoder.decompress(TEXT_ZST, &mut out2).unwrap();
    assert_eq!(out2, TEXT_BIN);
}
